       document.getElementById("app").innerHTML = ContactForm();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");
       const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
       const phonePattern = /^[\d\s()+-]{7,20}$/;

       function getError(field, input) {
         const value = input.value.trim();

         if (field.required && value === "") {
           return field.error;
         }

         if (field.name === "email" && value !== "" && !emailPattern.test(value)) {
           return field.error;
         }

         if (field.name === "phone" && value !== "" && !phonePattern.test(value)) {
           return field.error;
         }

         return "";
       }

       function setFieldError(input, message) {
         const errorMessage = document.getElementById(`${input.id}-error`);
         input.setAttribute("aria-invalid", message ? "true" : "false");
         errorMessage.textContent = message;
         errorMessage.classList.toggle("is-visible", Boolean(message));
       }

       function validateField(field) {
         const input = document.getElementById(field.id);
         const message = getError(field, input);
         setFieldError(input, message);
         return { input, message };
       }

       fields.forEach((field) => {
         const input = document.getElementById(field.id);

         input.addEventListener("blur", () => {
           validateField(field);
         });

         input.addEventListener("input", () => {
           if (input.getAttribute("aria-invalid") === "true") {
             validateField(field);
           }
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const results = fields.map(validateField);
         const firstInvalid = results.find(({ message }) => message);

         if (firstInvalid) {
           status.textContent = "Please correct the highlighted fields.";
           firstInvalid.input.focus();
           return;
         }

         status.textContent = "Thanks. Your support request is ready to send.";
         form.reset();
       });
     </script>
